export function CssVariable({
  accent = "{{accent}}",
  size = {{size}},
  radius = {{radius}},
  bound = {{bound}},
}) {
  const color = bound ? accent : "#cccccc";
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 320, "--accent": accent }}
      role="img" aria-label="Three elements sharing one custom property; toggling the binding disconnects them">
      <pre style={{ background: "#241430", color: "#FAF7F2", padding: 12, borderRadius: 8, font: "12px/1.6 ui-monospace, monospace", margin: "0 0 14px" }}>
{`:root { --accent: ${accent}; }`}
      </pre>
      <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
        <div style={{ width: size, height: size, borderRadius: radius, background: color }} />
        <div style={{ width: size, height: size, borderRadius: radius, border: `4px solid ${color}`, background: "#FAF7F2", boxSizing: "border-box" }} />
        <button type="button" style={{ padding: "8px 14px", borderRadius: 8, border: `1.5px solid ${bound ? accent : "#cccccc"}`,
          background: "transparent", color: bound ? accent : "#999999", fontWeight: 600, fontSize: 13 }}>
          Button
        </button>
      </div>
      <p style={{ marginTop: 14, fontSize: 12, color: "#241430cc" }}>
        {bound ? "All three read var(--accent) — one edit updates every consumer at once." : "Disconnected — each would need its own edit to match."}
      </p>
    </div>
  );
}
